using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Driving;
using HarborValeGreybox.Racing;
using HarborValeGreybox.Launch;
namespace HarborValeGreybox.Garage {
public class GarageUiProbe:MonoBehaviour {
 static string folder;List<string> lines=new List<string>();bool failed;double deadline;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--garage-ui-dir");folder=Debug.isDebugBuild&&i>=0&&i+1<args.Length?Path.GetFullPath(args[i+1]):null;if(folder!=null){Directory.CreateDirectory(folder);DocksideTrialDirector.SavePathOverrideForTests=Path.Combine(folder,"profile-v3.json");}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Hook(){if(folder==null)return;var root=new GameObject("Garage interface native checks");DontDestroyOnLoad(root);root.AddComponent<GarageUiProbe>();}
 void Check(bool yes,string text){lines.Add((yes?"PASS ":"FAIL ")+text);if(!yes){Write();Application.Quit(1);throw new Exception(text);}}
 void Write(){File.WriteAllLines(Path.Combine(folder,"native-results.txt"),lines);}
 void Log(string m,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){failed=true;lines.Add("ERROR "+m);Write();Application.Quit(1);}}
 void Update(){if(!failed&&deadline>0&&Time.realtimeSinceStartupAsDouble>deadline){failed=true;lines.Add("FAIL timeout");Write();Application.Quit(1);}}
 IEnumerator Wait(Func<bool> ready){double until=Time.realtimeSinceStartupAsDouble+30;while(!ready()){if(Time.realtimeSinceStartupAsDouble>until){Check(false,"Wait timeout");yield break;}yield return null;}yield return new WaitForSecondsRealtime(.3f);}
 IEnumerator Capture(string name){yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return new WaitForSecondsRealtime(.3f);}
 static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var gate in d.checkpoints)s.Tick(.02f,gate.Position-gate.Forward,gate.Position+gate.Forward);return s;}
 IEnumerator Start(){deadline=Time.realtimeSinceStartupAsDouble+120;Application.logMessageReceived+=Log;yield return new WaitForSecondsRealtime(.5f);Check(HarborValeLaunch.Instance.Open(HarborValeLaunch.CityScene),"Hub opens Finch drive");yield return Wait(()=>UnityEngine.Object.FindAnyObjectByType<FinchGarage>()?.Catalog!=null);var garage=UnityEngine.Object.FindAnyObjectByType<FinchGarage>();var trial=garage.Trial;for(int i=0;i<4;i++)trial.Store.Settle(Finish(trial.Definition),out _);Check(garage.Open(),"Garage interface opens through real modal");Check(trial.vehicle.controlsLocked&&!trial.vehicle.GetComponent<FinchDrivingHUD>().enabled,"Driving/shift HUD hidden and controls locked in shop");yield return Capture("Garage_Overview");garage.View.Search="turbo";garage.View.SetCategory(1);Check(garage.View.Visible().Count==1&&garage.SelectedIndex==2,"Search and category filter find turbo");Check(garage.View.Dependencies(garage.Offers[2]).Count==2,"Turbo exposes both Stage1 and gearbox prerequisites");Check(garage.View.Dependencies(garage.Offers[3]).Count==3,"Cooling exposes the full three-part prerequisite path");yield return Capture("Garage_LockedTurbo");Check(garage.View.ShowRequiredPart()&&garage.SelectedIndex==0,"Requirement action selects missing Stage1");Check(garage.BuySelected()&&trial.Store.Profile.availableCredits==2800,"Visible Stage1 action purchases once");garage.Select(2);Check(garage.View.ShowRequiredPart()&&garage.SelectedIndex==1,"Turbo guidance selects missing gearbox");Check(garage.BuySelected(),"Gearbox installed from guided flow");garage.Select(2);Check(garage.BuySelected(),"Turbo installed from real purchase flow");garage.Select(3);Check(garage.BuySelected()&&trial.Store.Profile.availableCredits==250,"Intercooler installed with exact remaining balance");int balance=trial.Store.Profile.availableCredits;garage.BuySelected();Check(trial.Store.Profile.availableCredits==balance,"Repeated install cannot charge again");yield return Capture("Garage_InstalledBuild");garage.View.Search="no matching part";garage.View.SetCategory(0);Check(garage.View.Visible().Count==0,"Empty search returns a clear no-results state");yield return Capture("Garage_NoResults");garage.View.Search="";garage.View.SetCategory(0);garage.Close();yield return null;Check(!trial.vehicle.controlsLocked&&trial.vehicle.GetComponent<FinchDrivingHUD>().enabled,"Closing restores driving HUD/input");for(int i=0;i<3;i++){Check(garage.Open(),"Repeated garage open "+i);garage.Close();yield return null;}Check(UnityEngine.Object.FindObjectsByType<FinchVehicle>(FindObjectsSortMode.None).Length==1&&UnityEngine.Object.FindObjectsByType<WheelCollider>(FindObjectsSortMode.None).Length==4,"Preview never duplicates vehicle physics");Check(GameObject.Find("Garage render preview | visual only")==null,"Preview camera/model cleaned up on close");Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.6f);Check(garage.Open(),"Garage opens at 1280x720");yield return Capture("Garage_1280x720");garage.Close();Screen.SetResolution(1600,900,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.6f);Check(garage.Open(),"Garage opens at 1600x900");yield return Capture("Garage_1600x900");garage.Close();Check(new RaceProgressStore(trial.Store.PathName,trial.Definition).Profile.spending.Count==4,"All four real purchases persist after UI changes");Check(!failed,"No native runtime errors");Write();Application.Quit(0);
 }
}
}
